import { createElement, useState } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { parse, serialize, getBlockType } from '@wordpress/blocks';
import { registerCoreBlocks } from '@wordpress/block-library';
import '@wordpress/format-library';
import {
  BlockEditorProvider,
  BlockList,
  BlockInspector,
  BlockTools,
  BlockToolbar,
  Inserter,
  WritingFlow,
  ObserveTyping,
} from '@wordpress/block-editor';
import { Button, Popover, SlotFillProvider, TabPanel, PanelBody } from '@wordpress/components';
import { uploadMedia } from '@wordpress/media-utils';
import { decodeEntities } from '@wordpress/html-entities';

const LESSON_BLOCKS = [
  'core/paragraph',
  'core/heading',
  'core/list',
  'core/list-item',
  'core/image',
  'core/gallery',
  'core/video',
  'core/audio',
  'core/file',
  'core/embed',
  'core/quote',
  'core/pullquote',
  'core/table',
  'core/code',
  'core/preformatted',
  'core/separator',
  'core/spacer',
  'core/buttons',
  'core/button',
  'core/columns',
  'core/column',
  'core/group',
  'core/cover',
  'core/freeform',
  'core/html',
];

/** A full lesson workspace: the inspector shares the block provider with the writing canvas. */
export function LessonBlockWorkspace({
  lesson,
  onTitleChange,
  onContentChange,
  settings,
  media,
  customContent,
}) {
  if (!getBlockType('core/paragraph')) registerCoreBlocks();
  const [blocks, setBlocks] = useState(() => parse(lesson.description || ''));
  const [showSettings, setShowSettings] = useState(true);
  const [editorSettings] = useState(() => ({
    ...(window.ohmylmsLessonBlockSettings || {}),
    allowedBlockTypes: LESSON_BLOCKS,
    hasFixedToolbar: true,
    mediaUpload: (options) => uploadMedia({ ...options, additionalData: { post: lesson.id } }),
  }));
  function changeBlocks(next) {
    setBlocks(next);
    onContentChange(serialize(next));
  }
  return (
    <SlotFillProvider>
      <BlockEditorProvider
        value={blocks}
        onInput={changeBlocks}
        onChange={changeBlocks}
        settings={editorSettings}
      >
        <section
          className="ohmylms-lesson-block-workspace"
          aria-label={__('Lesson block editor', 'ohmylms')}
        >
          <div
            className="ohmylms-lesson-block-toolbar"
            role="toolbar"
            aria-label={__('Lesson editor tools', 'ohmylms')}
          >
            {!customContent && (
              <>
                <Inserter
                  renderToggle={({ onToggle, isOpen }) => (
                    <Button variant="primary" icon="plus" onClick={onToggle} aria-expanded={isOpen}>
                      {__('Add block', 'ohmylms')}
                    </Button>
                  )}
                />
                <BlockToolbar />
              </>
            )}
            <Button
              className="ohmylms-lesson-inspector-toggle"
              icon="admin-generic"
              isPressed={showSettings}
              aria-expanded={showSettings}
              onClick={() => setShowSettings(!showSettings)}
            >
              {__('Settings', 'ohmylms')}
            </Button>
          </div>
          <div className={`ohmylms-lesson-block-body${showSettings ? ' has-inspector' : ''}`}>
            <div className="ohmylms-lesson-block-canvas">
              <div className="ohmylms-lesson-block-document editor-styles-wrapper">
                <input
                  className="ohmylms-lesson-block-title"
                  aria-label={__('Lesson title', 'ohmylms')}
                  placeholder={__('Enter lesson title', 'ohmylms')}
                  value={decodeEntities(lesson.title ?? lesson.name ?? '')}
                  onChange={(event) => onTitleChange(event.target.value)}
                />
                {customContent || (
                  <BlockTools>
                    <WritingFlow>
                      <ObserveTyping>
                        <BlockList />
                      </ObserveTyping>
                    </WritingFlow>
                  </BlockTools>
                )}
              </div>
            </div>
            {showSettings && (
              <aside
                className="ohmylms-lesson-block-inspector"
                aria-label={__('Editor settings', 'ohmylms')}
              >
                <TabPanel
                  tabs={[
                    { name: 'lesson', title: __('Lesson', 'ohmylms') },
                    ...(!customContent ? [{ name: 'block', title: __('Block', 'ohmylms') }] : []),
                  ]}
                >
                  {(tab) =>
                    tab.name === 'block' ? (
                      <BlockInspector />
                    ) : (
                      <>
                        <PanelBody title={__('Lesson media', 'ohmylms')} initialOpen={false}>
                          {media}
                        </PanelBody>
                        <div className="ohmylms-lesson-document-settings">{settings}</div>
                      </>
                    )
                  }
                </TabPanel>
              </aside>
            )}
          </div>
          <Popover.Slot />
        </section>
      </BlockEditorProvider>
    </SlotFillProvider>
  );
}
